const std = @import("std");

pub fn main() !void {
    var arr = [_]i32{ 1, 2, 3, 4, 5 };

    for (0..arr.len / 2) |i| {
        const j = arr.len - 1 - i;
        const temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    for (arr) |val| {
        std.debug.print("{} ", .{val});
    }
    std.debug.print("\n", .{});
}
